import { z } from 'zod';
import type { HttpClient } from '@wix/cli-http-client';
import type { ComponentGenerationResult } from '@wix/gena';
import type { WixAstroConfig } from '@wix/cli-astro-definitions';
import type { ProjectModel } from '../../../model.js';

type ExtensionGroup = 'Dashboard' | 'Backend' | 'Site';

export type ExtensionProjectType = WixAstroConfig['projectType'];

interface ExtensionGenerate<TData> {
  projectFolder: string;
  appId: string;
  model: ProjectModel;
  data: TData;
  httpClient: HttpClient;
}

export interface ExtensionDef<
  T extends z.ZodTypeAny = z.ZodTypeAny,
  TData = z.infer<T>,
> {
  title: string;
  description?: string;
  group: ExtensionGroup;
  /**
   * Project types this extension can be generated in. Extensions are hidden
   * from the picker, rejected by `--type`/`--params` and omitted from the
   * `wix schema generate` output in projects of any other type.
   */
  projectTypes: readonly [ExtensionProjectType, ...ExtensionProjectType[]];
  documentation?: string;
  zodSchema:
    | z.ZodTypeAny
    | ((httpClient: HttpClient) => z.ZodTypeAny | Promise<z.ZodTypeAny>);
  enrich?: (data: z.infer<T>) => TData;
  generate: (
    options: ExtensionGenerate<TData>
  ) => Promise<ComponentGenerationResult | void>;
  validate?: (projectFolder: string, data: TData) => Promise<string | null>;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type AnyExtensionDef = ExtensionDef<any, any>;

export const extensionFieldDefinitionSchema = z.object({
  title: z.string(),
  description: z.string().optional(),
  default: z.unknown().optional(),
});

export type ExtensionFieldDefinition = z.infer<
  typeof extensionFieldDefinitionSchema
>;

export const extensionTypeSchema = z.object({
  extensionType: z.string(),
});
